using System;
using System.Linq;
using UnityEditor;
using UnityEditor.Animations;
using UnityEngine;
using nadena.dev.modular_avatar.core;
using VRC.SDK3.Avatars.Components;
using VRC.SDK3.Avatars.ScriptableObjects;
using VRC.SDK3.Dynamics.Constraint.Components;
using VRC.Dynamics;
namespace MorphForgeAvatar.Editor {
 // Optional native Camera -> RT preview. No custom runtime scripts or copied particles.
 public static class LocalPreviewBuild {
  public const string Root=AvatarSetupWindow.Root+"/Generated/LocalPreview";
  public const string Enabled="MF_Preview",Corner="MF_PreviewCorner",Size="MF_PreviewSize",Zoom="MF_PreviewZoom",Oblique="MF_PreviewOblique";
  static string[] Names={Enabled,Corner,Size,Zoom,Oblique};
  static AnimatorController fx;
  static void Curve(AnimationClip c,string path,Type type,string property,float value){AnimationUtility.SetEditorCurve(c,EditorCurveBinding.FloatCurve(path,type,property),AnimationCurve.Constant(0,1,value));}
  static AnimationClip Clip(string name){var c=new AnimationClip{name=name};AssetDatabase.AddObjectToAsset(c,fx);return c;}
  static AnimatorStateMachine Layer(string name){var sm=new AnimatorStateMachine{name=name};AssetDatabase.AddObjectToAsset(sm,fx);fx.AddLayer(new AnimatorControllerLayer{name=name,stateMachine=sm,defaultWeight=1});return sm;}
  static AnimatorState State(AnimatorStateMachine sm,string name,Motion clip){var s=sm.AddState(name);s.motion=clip;s.writeDefaultValues=false;return s;}
  static AnimatorStateTransition Any(AnimatorStateMachine sm,AnimatorState s){var t=sm.AddAnyStateTransition(s);t.duration=0;t.hasExitTime=false;t.canTransitionToSelf=false;return t;}
  static void Bool(AnimatorStateTransition t,string name,bool value){t.AddCondition(value?AnimatorConditionMode.If:AnimatorConditionMode.IfNot,0,name);}
  static VRCExpressionsMenu Menu(string name,string path){var m=AssetDatabase.LoadAssetAtPath<VRCExpressionsMenu>(path);if(!m){m=ScriptableObject.CreateInstance<VRCExpressionsMenu>();AssetDatabase.CreateAsset(m,path);}m.name=name;m.controls.Clear();return m;}
  static VRCExpressionsMenu.Control Toggle(string label,string parameter,float value=1){return new VRCExpressionsMenu.Control{name=label,type=VRCExpressionsMenu.Control.ControlType.Toggle,parameter=new VRCExpressionsMenu.Control.Parameter{name=parameter},value=value};}
  static VRCExpressionsMenu.Control Radial(string label,string parameter){return new VRCExpressionsMenu.Control{name=label,type=VRCExpressionsMenu.Control.ControlType.RadialPuppet,subParameters=new[]{new VRCExpressionsMenu.Control.Parameter{name=parameter}}};}
  public static string Build(){
   if(EditorApplication.isPlaying)throw new Exception("Edit Mode required");CatalogVariant.EnsureFolder(Root);
   var texture=AssetDatabase.LoadAssetAtPath<RenderTexture>(Root+"/ReceivedView.renderTexture");if(!texture){texture=new RenderTexture(512,384,16,RenderTextureFormat.ARGB32){name="MorphForge received view",antiAliasing=2,useMipMap=false,autoGenerateMips=false};AssetDatabase.CreateAsset(texture,Root+"/ReceivedView.renderTexture");}
   var material=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Screen.mat");if(!material){material=new Material(Shader.Find("MorphForgeAvatar/LocalPreview"));AssetDatabase.CreateAsset(material,Root+"/Screen.mat");}material.mainTexture=texture;EditorUtility.SetDirty(material);
   var mesh=AssetDatabase.LoadAssetAtPath<Mesh>(Root+"/Screen.asset");if(!mesh){mesh=new Mesh{name="MorphForge preview panel",vertices=new[]{new Vector3(-.5f,-.5f,0),new Vector3(.5f,-.5f,0),new Vector3(.5f,.5f,0),new Vector3(-.5f,.5f,0)},uv=new[]{Vector2.zero,Vector2.right,Vector2.one,Vector2.up},triangles=new[]{0,2,1,0,3,2}};mesh.RecalculateBounds();mesh.RecalculateNormals();AssetDatabase.CreateAsset(mesh,Root+"/Screen.asset");}
   var path=Root+"/Preview.controller";fx=AssetDatabase.LoadAssetAtPath<AnimatorController>(path);if(!fx)fx=AnimatorController.CreateAnimatorControllerAtPath(path);else{fx.layers=new AnimatorControllerLayer[0];fx.parameters=new AnimatorControllerParameter[0];foreach(var a in AssetDatabase.LoadAllAssetsAtPath(path))if(a&&a!=fx)UnityEngine.Object.DestroyImmediate(a,true);}
   foreach(var n in Names)fx.AddParameter(new AnimatorControllerParameter{name=n,type=n==Corner?AnimatorControllerParameterType.Int:n==Enabled||n==Oblique?AnimatorControllerParameterType.Bool:AnimatorControllerParameterType.Float,defaultFloat=.5f});fx.AddParameter("IsLocal",AnimatorControllerParameterType.Bool);
   var sm=Layer("Owner preview gate");var off=Clip("Off");var on=Clip("On");foreach(string p in new[]{"CaptureRig/Camera","HeadRig/Panel"}){Curve(off,p,typeof(GameObject),"m_IsActive",0);Curve(on,p,typeof(GameObject),"m_IsActive",1);}var disabled=State(sm,"Disabled",off);var active=State(sm,"Enabled for owner",on);sm.defaultState=disabled;var t=Any(sm,active);Bool(t,"IsLocal",true);Bool(t,Enabled,true);t=Any(sm,disabled);Bool(t,"IsLocal",false);t=Any(sm,disabled);Bool(t,Enabled,false);
   sm=Layer("Preview corner");string[] labels={"左侧","右侧","左上","右上","左下","右下"};for(int i=0;i<6;i++){var c=Clip(labels[i]);Curve(c,"HeadRig/Panel",typeof(Transform),"m_LocalPosition.x",i%2==0?-.23f:.23f);Curve(c,"HeadRig/Panel",typeof(Transform),"m_LocalPosition.y",i<2?-.03f:i<4?.15f:-.2f);Curve(c,"HeadRig/Panel",typeof(Transform),"m_LocalPosition.z",.55f);var state=State(sm,labels[i],c);if(i==3)sm.defaultState=state;t=Any(sm,state);t.AddCondition(AnimatorConditionMode.Equals,i,Corner);}
   foreach(bool zoom in new[]{false,true}){var parameter=zoom?Zoom:Size;sm=Layer(parameter);var tree=new BlendTree{name=parameter,blendType=BlendTreeType.Simple1D,blendParameter=parameter,useAutomaticThresholds=false};AssetDatabase.AddObjectToAsset(tree,fx);for(int i=0;i<2;i++){var c=Clip(parameter+i);if(zoom)Curve(c,"CaptureRig/Camera",typeof(Camera),"field of view",i==0?55:15);else{Curve(c,"HeadRig/Panel",typeof(Transform),"m_LocalScale.x",i==0?.16f:.4f);Curve(c,"HeadRig/Panel",typeof(Transform),"m_LocalScale.y",i==0?.12f:.3f);Curve(c,"HeadRig/Panel",typeof(Transform),"m_LocalScale.z",1);}tree.AddChild(c,i);}sm.defaultState=State(sm,"Adjust",tree);}
   sm=Layer("Preview view");for(int i=0;i<2;i++){var c=Clip("View "+i);var pos=i==0?new Vector3(0,0,-140):new Vector3(100,75,-140);var q=Quaternion.LookRotation(-pos,Vector3.up);foreach(var a in Enumerable.Range(0,3))Curve(c,"CaptureRig/Camera",typeof(Transform),"m_LocalPosition."+"xyz"[a],pos[a]);foreach(var a in Enumerable.Range(0,4))Curve(c,"CaptureRig/Camera",typeof(Transform),"m_LocalRotation."+"xyzw"[a],q[a]);var st=State(sm,"View "+i,c);if(i==0)sm.defaultState=st;t=Any(sm,st);Bool(t,Oblique,i==1);}
   var corners=Menu("预览位置",Root+"/Corners.asset");for(int i=0;i<6;i++)corners.controls.Add(Toggle(labels[i],Corner,i));var menu=Menu("本人预览",Root+"/Menu.asset");menu.controls.Add(Toggle("显示预览",Enabled));menu.controls.Add(new VRCExpressionsMenu.Control{name="位置",type=VRCExpressionsMenu.Control.ControlType.SubMenu,subMenu=corners});menu.controls.Add(Radial("面板大小",Size));menu.controls.Add(Radial("取景缩放",Zoom));menu.controls.Add(Toggle("斜视取景",Oblique));var installMenu=Menu("MorphForge preview",Root+"/InstallMenu.asset");installMenu.controls.Add(new VRCExpressionsMenu.Control{name="本人预览",type=VRCExpressionsMenu.Control.ControlType.SubMenu,subMenu=menu});EditorUtility.SetDirty(installMenu);EditorUtility.SetDirty(menu);EditorUtility.SetDirty(corners);EditorUtility.SetDirty(fx);AssetDatabase.SaveAssets();return "Native owner preview assets built (512x384, default off, 0 synced bits)";
  }
  static GameObject Child(Transform parent,string name){var t=parent.Find(name);if(t)return t.gameObject;var g=new GameObject(name);g.transform.SetParent(parent,false);return g;}
  static void Follow(GameObject go,Transform target){var c=go.GetComponent<VRCParentConstraint>();if(!c)c=go.AddComponent<VRCParentConstraint>();c.Sources.Clear();c.Sources.Add(new VRCConstraintSource{SourceTransform=target,Weight=1});c.IsActive=true;c.Locked=true;c.GlobalWeight=1;c.SolveInLocalSpace=false;c.AffectsPositionX=c.AffectsPositionY=c.AffectsPositionZ=true;c.AffectsRotationX=c.AffectsRotationY=c.AffectsRotationZ=true;c.PositionAtRest=Vector3.zero;c.RotationAtRest=Vector3.zero;c.FreezeToWorld=false;}
  public static void Install(GameObject module){
   var center=module.GetComponentsInChildren<ModularAvatarMergeAnimator>(true).Single(m=>m.gameObject.name=="MF6Decoder").transform.parent;
   var root=Child(module.transform,"LocalPreview");var head=Child(root.transform,"HeadReference");var proxy=head.GetComponent<ModularAvatarBoneProxy>();if(!proxy)proxy=head.AddComponent<ModularAvatarBoneProxy>();proxy.boneReference=HumanBodyBones.Head;proxy.attachmentMode=BoneProxyAttachmentMode.AsChildAtRoot;proxy.matchScale=false;
   var headRig=Child(root.transform,"HeadRig");Follow(headRig,head.transform);var panel=Child(headRig.transform,"Panel");var filter=panel.GetComponent<MeshFilter>();if(!filter)filter=panel.AddComponent<MeshFilter>();filter.sharedMesh=AssetDatabase.LoadAssetAtPath<Mesh>(Root+"/Screen.asset");var renderer=panel.GetComponent<MeshRenderer>();if(!renderer)renderer=panel.AddComponent<MeshRenderer>();renderer.sharedMaterial=AssetDatabase.LoadAssetAtPath<Material>(Root+"/Screen.mat");renderer.shadowCastingMode=UnityEngine.Rendering.ShadowCastingMode.Off;renderer.receiveShadows=false;panel.transform.localPosition=new Vector3(.23f,.15f,.55f);panel.transform.localScale=new Vector3(.28f,.21f,1);panel.SetActive(false);
   var capture=Child(root.transform,"CaptureRig");Follow(capture,center);var scale=capture.GetComponent<VRCScaleConstraint>();if(!scale)scale=capture.AddComponent<VRCScaleConstraint>();scale.Sources.Clear();scale.Sources.Add(new VRCConstraintSource{SourceTransform=center,Weight=1});scale.IsActive=true;scale.Locked=true;scale.GlobalWeight=1;scale.SolveInLocalSpace=false;scale.AffectsScaleX=scale.AffectsScaleY=scale.AffectsScaleZ=true;scale.ScaleAtRest=Vector3.one;scale.ScaleOffset=Vector3.one;var cameraObject=Child(capture.transform,"Camera");var camera=cameraObject.GetComponent<Camera>();if(!camera)camera=cameraObject.AddComponent<Camera>();camera.targetTexture=AssetDatabase.LoadAssetAtPath<RenderTexture>(Root+"/ReceivedView.renderTexture");camera.orthographic=false;camera.fieldOfView=35;camera.nearClipPlane=.01003125f;camera.farClipPlane=4093.125f;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=new Color(.025f,.03f,.04f,1);camera.allowHDR=false;camera.allowMSAA=true;camera.stereoTargetEye=StereoTargetEyeMask.None;camera.depth=-90;camera.cullingMask=~0;cameraObject.transform.localPosition=new Vector3(0,0,-140);cameraObject.transform.localRotation=Quaternion.identity;cameraObject.SetActive(false);
   var merge=root.GetComponent<ModularAvatarMergeAnimator>();if(!merge)merge=root.AddComponent<ModularAvatarMergeAnimator>();merge.animator=AssetDatabase.LoadAssetAtPath<AnimatorController>(Root+"/Preview.controller");merge.layerType=VRCAvatarDescriptor.AnimLayerType.FX;merge.pathMode=MergeAnimatorPathMode.Relative;merge.matchAvatarWriteDefaults=false;
   var parameters=root.GetComponent<ModularAvatarParameters>();if(!parameters)parameters=root.AddComponent<ModularAvatarParameters>();parameters.parameters.Clear();foreach(var n in Names)parameters.parameters.Add(new ParameterConfig{nameOrPrefix=n,syncType=n==Corner?ParameterSyncType.Int:n==Enabled||n==Oblique?ParameterSyncType.Bool:ParameterSyncType.Float,localOnly=true,saved=true,hasExplicitDefaultValue=true,defaultValue=n==Corner?3:n==Size||n==Zoom?.5f:0});
   var installer=root.GetComponent<ModularAvatarMenuInstaller>();if(!installer)installer=root.AddComponent<ModularAvatarMenuInstaller>();installer.menuToAppend=AssetDatabase.LoadAssetAtPath<VRCExpressionsMenu>(Root+"/InstallMenu.asset");
  }
 }
}
